from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

from itertools import combinations, product
import heapq


def _dependency_solver(data, name_order, preference):
    packages = data["packages"]
    names = sorted(packages, reverse=name_order == "descending")
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    choices = []
    for name in names:
        rows = [row for row in packages[name]
                if row["version"] not in blocked.get(name, [])
                and (name not in pins or row["version"] == pins[name])]
        choices.append([None] + rows)

    best_vector = None
    best_versions = None
    for selection in product(*choices):
        installed = {name: row for name, row in zip(names, selection)
                     if row is not None}
        if any(root not in installed or
               not bounds[0] <= installed[root]["version"] <= bounds[1]
               for root, bounds in data["roots"].items()):
            continue

        edges = {name: [] for name in installed}
        valid = True
        for name, row in installed.items():
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = installed.get(dep["name"])
                if (target is None or
                        not dep["min"] <= target["version"] <= dep["max"]):
                    valid = False
                    break
                edges[name].append(dep["name"])
            if not valid:
                break
        if not valid:
            continue

        # Installed packages must be precisely the roots' active dependency closure.
        closure = set()
        pending = list(data["roots"])
        while pending:
            name = pending.pop()
            if name in closure:
                continue
            closure.add(name)
            pending.extend(edges[name])
        if closure != set(installed):
            continue

        visiting, finished = set(), set()

        def visit(name):
            if name in visiting:
                return False
            if name in finished:
                return True
            visiting.add(name)
            if any(not visit(other) for other in edges[name]):
                return False
            visiting.remove(name)
            finished.add(name)
            return True

        if not all(visit(name) for name in edges):
            continue
        vector = tuple(installed[name]["version"] if name in installed else -1
                       for name in names)
        better = (best_vector is None or
                  (vector > best_vector if preference == "maximum"
                   else vector < best_vector))
        if better:
            best_vector = vector
            best_versions = {name: row["version"]
                             for name, row in installed.items()}

    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


def _component_01(data):
    return _dependency_solver(data, "ascending", "maximum")


def _component_02(data):
    return _dependency_solver(data, "ascending", "minimum")


def _component_03(data):
    return _dependency_solver(data, "descending", "maximum")


def _component_04(data):
    return _dependency_solver(data, "descending", "minimum")


def _component_05(data):
    return _dependency_solver(data, "ascending", "maximum")


def _component_06(data):
    def rounded(numerator, mode):
        if mode == "half_up":
            return (numerator + 5000) // 10000
        return numerator // 10000

    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        key = (event.get("revision", 0), pos)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), data["rounding"])
        tax = rounded(net * event.get("tax_bp", 0), data["rounding"])
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = (event.get("account", "default") + "|" +
               event.get("currency", "USD"))
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _component_07(data):
    blocked = set(data.get("blocked", []))
    jobs = [job for job in data["jobs"] if job["id"] not in blocked]
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    k = data["k"]
    best_value = None
    best_ids = None

    for selection in combinations(jobs, k):
        ids = {job["id"] for job in selection}
        if not mandatory <= ids:
            continue
        counts = {}
        for job in selection:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue

        active_ends = []
        compatible = True
        for job in sorted(selection,
                          key=lambda row: (row["start"], row["end"], row["id"])):
            while active_ends and active_ends[0] <= job["start"]:
                heapq.heappop(active_ends)
            heapq.heappush(active_ends, job["end"])
            if len(active_ends) > 2:
                compatible = False
                break
        if not compatible:
            continue

        value = sum(job["value"] for job in selection)
        selected_ids = sorted(ids)
        if (best_value is None or value > best_value or
                (value == best_value and selected_ids < best_ids)):
            best_value, best_ids = value, selected_ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _component_08(data):
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    required_bits = {node: 1 << i
                     for i, node in enumerate(data.get("required", []))}
    full_mask = (1 << len(required_bits)) - 1
    source = data["source"]
    initial_mask = required_bits.get(source, 0)
    initial_left = data["coupons"]
    initial_state = (source, initial_mask, initial_left)
    start = data["start"]
    distances = {initial_state: start}
    queue = [(start, source, initial_mask, initial_left)]

    while queue:
        arrival, node, mask, left = heapq.heappop(queue)
        state = (node, mask, left)
        if distances.get(state) != arrival:
            continue
        if node == data["target"] and mask == full_mask:
            return {"arrival": arrival}

        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], left)]
            if left:
                options.append((max(2, edge["duration"] - edge.get("discount", 0)),
                                left - 1))
            next_mask = mask | required_bits.get(edge["v"], 0)
            for duration, next_left in options:
                next_arrival = depart + duration
                if next_arrival > data["deadline"]:
                    continue
                next_state = (edge["v"], next_mask, next_left)
                if next_arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = next_arrival
                    heapq.heappush(queue, (next_arrival, *next_state))
    return {"arrival": None}


